     1→import { Block, Screen, Text } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import { useAtom } from "jotai";
     4→import { MatrixService } from "modules/matrix-client/services";
     5→import { addDateDividers, getEventId } from "modules/matrix-client/utils";
     6→import { TimelineAtoms } from "modules/timeline/jotai/atoms";
     7→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
     8→import {
     9→  ActivityIndicator,
    10→  FlatList,
    11→  Image,
    12→  KeyboardAvoidingView,
    13→  type NativeScrollEvent,
    14→  type NativeSyntheticEvent,
    15→  StyleSheet,
    16→} from "react-native";
    17→import { useSafeAreaInsets } from "react-native-safe-area-context";
    18→import {
    19→  Button,
    20→  ImageViewerModal,
    21→  Loading,
    22→  VideoViewerModal,
    23→} from "shared/components";
    24→import { Colors } from "shared/styles";
    25→import {
    26→  DateDivider,
    27→  MessageContentBottomSheet,
    28→  RoomHeader,
    29→  RoomInput,
    30→  SingleMessageType,
    31→} from "./fragments";
    32→import { useRoomInitialization, useRoomTimeline } from "./hooks";
    33→import { filterSameStateKey, handleIsPreviousSameSender } from "./utils";
    34→
    35→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
    36→  route,
    37→  navigation,
    38→}) => {
    39→  const { roomId } = route.params;
    40→  const client = MatrixService.instance;
    41→  const room = client?.getRoom(roomId);
    42→  const insets = useSafeAreaInsets();
    43→  const flatListRef = useRef<FlatList>(null);
    44→  /* Track whether list is scrolled to bottom */
    45→  const isAtBottomRef = useRef(true);
    46→  const [showScrollDown, setShowScrollDown] = useState(false);
    47→  const hasActiveCall = room?.hasActiveRoomCall();
    48→
    49→  const {
    50→    events,
    51→    loadingMessage,
    52→    refreshing,
    53→    updateTrigger,
    54→    loadMoreMessages,
    55→    markAsRead,
    56→  } = useRoomTimeline({
    57→    room,
    58→    roomId,
    59→  });
    60→
    61→  const { roomMembers, hasNoCallOption } = useRoomInitialization({ room });
    62→
    63→  const [scrollToEventId, setScrollToEventId] = useAtom(
    64→    TimelineAtoms.scrollToEventId,
    65→  );
    66→
    67→  const sortedEvents = useMemo(() => {
    68→    const sorted = [...events].sort(
    69→      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    70→    );
    71→
    72→    return filterSameStateKey(sorted);
    73→  }, [events]);
    74→
    75→  /**Events with date dividers */
    76→  const eventsWithDividers = useMemo(() => {
    77→    return addDateDividers(sortedEvents);
    78→  }, [sortedEvents]);
    79→
    80→  const handleScrollToEvent = useCallback(
    81→    (eventId: string) => {
    82→      const index = eventsWithDividers.findIndex(
    83→        (item) => item.type === "event" && getEventId(item.data) === eventId,
    84→      );
    85→      if (index === -1) return;
    86→
    87→      flatListRef.current?.scrollToIndex({
    88→        index,
    89→        animated: true,
    90→        viewPosition: 0.5,
    91→      });
    92→    },
    93→    [eventsWithDividers],
    94→  );
    95→
    96→  // Scroll to event when user clicks on a reply
    97→  useEffect(() => {
    98→    if (!scrollToEventId) return;
    99→    handleScrollToEvent(scrollToEventId);
   100→    setScrollToEventId(null);
   101→  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
   102→
   103→  const handleLoadMore = async () => {
   104→    setShowScrollDown(false);
   105→    await loadMoreMessages();
   106→  };
   107→
   108→  const handleScrollDown = () => {
   109→    flatListRef.current?.scrollToEnd({ animated: true });
   110→    setShowScrollDown(false);
   111→  };
   112→
   113→  const handleOnScroll = ({
   114→    nativeEvent,
   115→  }: NativeSyntheticEvent<NativeScrollEvent>) => {
   116→    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
   117→    const paddingToBottom = 100;
   118→    const atBottom =
   119→      layoutMeasurement.height + contentOffset.y >=
   120→      contentSize.height - paddingToBottom;
   121→    isAtBottomRef.current = atBottom;
   122→    if (!atBottom) return;
   123→    setShowScrollDown(false);
   124→    markAsRead();
   125→  };
   126→
   127→  // Show scroll down button if not at bottom and not own message
   128→  useEffect(() => {
   129→    if (isAtBottomRef.current || sortedEvents[0]?.isOwn) return;
   130→
   131→    setShowScrollDown(true);
   132→  }, [sortedEvents]);
   133→
   134→  const handleStartCall = () => {
   135→    if (!client || !room) {
   136→      console.error("Client or room not available");
   137→      return;
   138→    }
   139→
   140→    navigation.navigate("elementCall", {
   141→      roomId,
   142→      roomName: room.displayName(),
   143→    });
   144→  };
   145→
   146→  if (!room) return null;
   147→
   148→  return (
   149→    <Screen hideTopSafeArea scrollable={false}>
   150→      <RoomHeader
   151→        room={room}
   152→        roomMembers={roomMembers}
   153→        hasActiveCall={hasActiveCall ?? false}
   154→        hasNoCallOption={hasNoCallOption}
   155→        topInset={insets.top}
   156→        onBack={() => navigation.goBack()}
   157→        onRoomDetails={() => navigation.navigate("roomDetails", { room })}
   158→        onStartCall={handleStartCall}
   159→      />
   160→
   161→      {loadingMessage ? (
   162→        <Loading />
   163→      ) : (
   164→        <KeyboardAvoidingView style={{ flex: 1 }} behavior="padding">
   165→          {refreshing && (
   166→            <Block align="center" justify="center" width="100%" paddings={40}>
   167→              <ActivityIndicator size="large" color={Colors.primary} />
   168→            </Block>
   169→          )}
   170→          <FlatList
   171→            ref={flatListRef}
   172→            data={eventsWithDividers}
   173→            keyExtractor={(item) => {
   174→              if (item.type === "divider") return item.id;
   175→
   176→              return getEventId(item.data) ?? "";
   177→            }}
   178→            extraData={updateTrigger}
   179→            contentContainerStyle={styles.listContent}
   180→            onContentSizeChange={() => {
   181→              if (!isAtBottomRef.current) return;
   182→              // Auto-scroll only if already at the bottom
   183→              flatListRef.current?.scrollToEnd({ animated: false });
   184→            }}
   185→            onRefresh={handleLoadMore}
   186→            refreshing={refreshing}
   187→            onScroll={handleOnScroll}
   188→            onScrollToIndexFailed={(info) => {
   189→              flatListRef.current?.scrollToOffset({
   190→                offset: info.averageItemLength * info.index,
   191→                animated: true,
   192→              });
   193→            }}
   194→            renderItem={({ item }) => {
   195→              if (item.type === "divider") {
   196→                return <DateDivider date={item.date} />;
   197→              }
   198→
   199→              // For events, calculate the index in the original sortedEvents array
   200→              const eventIndex = sortedEvents.findIndex(
   201→                (e) => getEventId(e) === getEventId(item.data),
   202→              );
   203→
   204→              return (
   205→                <SingleMessageType
   206→                  event={item.data}
   207→                  isPreviousSameSender={handleIsPreviousSameSender(
   208→                    sortedEvents,
   209→                    item.data,
   210→                    eventIndex,
   211→                  )}
   212→                />
   213→              );
   214→            }}
   215→          />
   216→          <MessageContentBottomSheet roomId={roomId} />
   217→
   218→          {showScrollDown && (
   219→            <Block
   220→              absolute
   221→              offsets={{ right: 0, bottom: 100 }}
   222→              align="center"
   223→              justify="center"
   224→              width="100%"
   225→            >
   226→              <Button.Outline size="medium" onPress={handleScrollDown}>
   227→                <Text>New messages</Text>
   228→                <Image source={require("assets/icons/arrow-down.png")} />
   229→              </Button.Outline>
   230→            </Block>
   231→          )}
   232→          <RoomInput roomId={roomId} />
   233→        </KeyboardAvoidingView>
   234→      )}
   235→      <ImageViewerModal />
   236→      <VideoViewerModal />
   237→    </Screen>
   238→  );
   239→};
   240→
   241→const styles = StyleSheet.create({
   242→  image: {
   243→    width: 32,
   244→    height: 32,
   245→    borderRadius: 48,
   246→  },
   247→  listContent: {
   248→    paddingHorizontal: 20,
   249→    paddingTop: 12,
   250→    paddingBottom: 20,
   251→  },
   252→  callButton: {
   253→    width: 36,
   254→    height: 36,
   255→    borderRadius: 18,
   256→    justifyContent: "center",
   257→    alignItems: "center",
   258→  },
   259→  callIcon: {
   260→    width: 20,
   261→    height: 20,
   262→    resizeMode: "contain",
   263→  },
   264→  callButtonCustom: {
   265→    backgroundColor: "rgba(255, 255, 255, 0.2)",
   266→    borderRadius: 18,
   267→    paddingHorizontal: 12,
   268→    paddingVertical: 8,
   269→  },
   270→  chatButton: {
   271→    display: "flex",
   272→    gap: 12,
   273→    flex: 1,
   274→    flexDirection: "column",
   275→  },
   276→  phoneIcon: {
   277→    width: 16,
   278→    height: 16,
   279→  },
   280→  blurOverlay: {
   281→    position: "absolute",
   282→    top: 0,
   283→    left: 0,
   284→    right: 0,
   285→    bottom: 0,
   286→    zIndex: 1,
   287→    opacity: 0.5,
   288→    width: "120%",
   289→    pointerEvents: "none",
   290→  },
   291→});
