   363→          room,
   364→          timestamp: (await room.latestEvent())?.timestamp || 0,
   365→        })),
   366→      );
   367→
   368→      const filteredAndSortedRooms = sortedRooms
   369→        .filter(({ room }) => {
   370→          const membership = room.membership();
   371→
   372→          return (
   373→            membership !== Membership.Banned &&
   374→            membership !== Membership.Left &&
   375→            membership !== Membership.Knocked
   376→          );
   377→        })
   378→        .sort((a, b) => {
   379→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
   380→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
   381→          if (aInvited !== bInvited) return bInvited - aInvited;
   382→
   383→          return Number(b.timestamp) - Number(a.timestamp);
   384→        });
   385→
   386→      MatrixJotaiStore.set(
   387→        MatrixAtoms.roomList,
