   438→    if (!this.instance) throw new Error("Client not initialized");
   439→
   440→    try {
   441→      // First request with undefined auth_data (will always fail per UIA spec)
   442→      try {
   443→        await this.instance.deactivateAccount(undefined, true);
   444→      } catch {
   445→        // Expected to fail
   446→      }
   447→
   448→      console.log(this.instance.userId(), "userId");
   449→      const userId = this.instance.userId();
