   783→    userId: string,
   784→  ): Promise<string> => {
   785→    if (!this.instance) throw new Error("Client not initialized");
   786→
   787→    try {
   788→      // Check if a direct room already exists with this user
   789→      const rooms = this.instance.rooms();
   790→      for (const room of rooms) {
   791→        const roomInfo = await room.roomInfo();
   792→        if (roomInfo?.isDirect) {
   793→          const members = await room.members();
   794→          const memberList = members.nextChunk(100000) ?? [];
   795→          const hasUser = memberList.some((member) => member.userId === userId);
   796→          if (hasUser) {
   797→            return room.id();
   798→          }
   799→        }
   800→      }
   801→
   802→      // If no direct room exists, create one
   803→      const roomOptions: CreateRoomParameters = {
   804→        name: undefined,
   805→        topic: undefined,
   806→        preset: RoomPreset.PrivateChat,
   807→        avatar: undefined,
   808→        isEncrypted: true,
   809→        isDirect: true,
   810→        visibility: new RoomVisibility.Private(),
   811→        invite: [userId],
   812→        powerLevelContentOverride: undefined,
   813→        joinRuleOverride: undefined,
   814→        historyVisibilityOverride: undefined,
   815→        canonicalAlias: undefined,
   816→      };
   817→
   818→      const roomId = await this.instance.createRoom(roomOptions);
   819→      return roomId;
   820→    } catch (error) {
   821→      throw new Error(`Failed to get or create direct room: ${error}`);
   822→    }
   823→  };
